import{_ as s,c as t,o as r,ag as e}from"./chunks/framework.C86mscM5.js";const b=JSON.parse('{"title":"Harbor","description":"","frontmatter":{},"headers":[],"relativePath":"devops/registries/harbor.md","filePath":"devops/registries/harbor.md","lastUpdated":1788689791000}'),i={name:"devops/registries/harbor.md"};function n(l,a,o,p,d,h){return r(),t("div",null,a[0]||(a[0]=[e(`<h1 id="harbor" tabindex="-1"><a href="https://github.com/goharbor/harbor" target="_blank" rel="nofollow noopener noreferrer">Harbor</a> <a class="header-anchor" href="#harbor" aria-label="Permalink to &quot;[Harbor](https://github.com/goharbor/harbor)&quot;">​</a></h1><p><strong>Written in Go.</strong></p><p>Harbor 是一个开源的企业级容器镜像仓库，用来集中存储、管理和分发 Docker/OCI 镜像。可以把它理解成“企业内部自建的 Docker Hub”，尤其适合 Kubernetes 和私有化部署环境。</p><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><ul><li><strong>镜像仓库</strong>：按项目组织、推送和拉取容器镜像</li><li><strong>访问控制</strong>：支持用户、角色和项目级权限管理</li><li><strong>安全扫描</strong>：扫描镜像中的已知漏洞</li><li><strong>镜像签名与策略</strong>：帮助确保镜像来源可信</li><li><strong>跨仓库复制</strong>：在多个 Harbor 或其他镜像仓库之间同步镜像</li><li><strong>审计日志</strong>：记录登录、推送、删除等操作</li><li><strong>垃圾回收</strong>：清理不再使用的镜像层，释放存储空间</li><li><strong>OCI 支持</strong>：除了容器镜像，还能保存 Helm Chart 等 OCI Artifact</li><li><strong>高可用部署</strong>：适合生产环境和较大规模的企业集群</li></ul><h2 id="基本工作方式" tabindex="-1">基本工作方式 <a class="header-anchor" href="#基本工作方式" aria-label="Permalink to &quot;基本工作方式&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开发者构建镜像</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>推送到 Harbor</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>安全扫描与权限检查</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>Kubernetes / Docker 拉取镜像并部署</span></span></code></pre></div><p>例如，Harbor 地址为 <code>harbor.example.com</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> harbor.example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tag</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-app:1.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> harbor.example.com/team-a/my-app:1.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> harbor.example.com/team-a/my-app:1.0</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> harbor.example.com/team-a/my-app:1.0</span></span></code></pre></div><p>镜像地址通常由三部分组成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>harbor.example.com/team-a/my-app:1.0</span></span>
<span class="line"><span>└────仓库域名────┘ └项目┘ └镜像与标签┘</span></span></code></pre></div><h2 id="常见应用场景" tabindex="-1">常见应用场景 <a class="header-anchor" href="#常见应用场景" aria-label="Permalink to &quot;常见应用场景&quot;">​</a></h2><ol><li><p><strong>企业内部镜像托管</strong><br> 避免业务镜像上传到公共平台，也方便统一管理权限。</p></li><li><p><strong>Kubernetes 私有镜像仓库</strong><br> 集群通过 <code>imagePullSecrets</code> 登录 Harbor 并拉取私有镜像。</p></li><li><p><strong>CI/CD 流水线</strong><br> Jenkins、GitLab CI 或 GitHub Actions 构建镜像后推送到 Harbor，再触发部署。</p></li><li><p><strong>多地域镜像同步</strong><br> 将总部的镜像复制到不同机房，提升拉取速度并增强容灾能力。</p></li><li><p><strong>供应链安全</strong><br> 在部署前执行漏洞扫描、签名验证和准入策略检查。</p></li></ol><h2 id="harbor-与-docker-registry-的区别" tabindex="-1">Harbor 与 Docker Registry 的区别 <a class="header-anchor" href="#harbor-与-docker-registry-的区别" aria-label="Permalink to &quot;Harbor 与 Docker Registry 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>Docker Registry</th><th>Harbor</th></tr></thead><tbody><tr><td>镜像存储和分发</td><td>支持</td><td>支持</td></tr><tr><td>Web 管理界面</td><td>基本没有</td><td>完整</td></tr><tr><td>用户与角色权限</td><td>较弱</td><td>完善</td></tr><tr><td>漏洞扫描</td><td>通常需自行集成</td><td>内置集成</td></tr><tr><td>镜像复制</td><td>较弱</td><td>支持</td></tr><tr><td>审计日志</td><td>较弱</td><td>支持</td></tr><tr><td>企业级管理</td><td>需要大量扩展</td><td>开箱即用</td></tr></tbody></table><p>简单来说：<strong>Docker Registry 提供底层镜像仓库能力，而 Harbor 在它之上补充了安全、权限、审计和运维管理功能。</strong></p><p>Harbor 通常通过 Docker Compose 或 Helm 部署。小型环境可以单机安装，生产环境则通常配合 Kubernetes、外部数据库、Redis、对象存储和负载均衡器构建高可用架构。</p><h2 id="生产治理建议" tabindex="-1">生产治理建议 <a class="header-anchor" href="#生产治理建议" aria-label="Permalink to &quot;生产治理建议&quot;">​</a></h2><ul><li>发布标签设置为不可变，Kubernetes 生产清单优先引用镜像 digest。</li><li>Robot Account 按项目和流水线拆分，只授予推送或拉取所需权限。</li><li>为分支镜像、候选版本和正式版本分别设置保留规则。</li><li>定期执行漏洞数据库更新、镜像扫描和垃圾回收；垃圾回收前确认备份与复制状态。</li><li>将签名、SBOM 和构建来源与镜像 digest 关联，部署前由准入策略验证。</li><li>监控容量、复制失败、扫描失败、认证异常和证书到期。</li></ul><p>参见 <a href="./../security-reliability/dependency-and-image-security.html">依赖与镜像安全</a>和 <a href="./../security-reliability/sbom.html">SBOM 与供应链证明</a>。</p>`,20)]))}const g=s(i,[["render",n]]);export{b as __pageData,g as default};
